    """OpenAI Chat Completions -> (template messages, template tools, template kwargs)."""
    messages = []

    raw = req.get("messages", [])
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)      # client double-encoded messages as a JSON string
        except ValueError:
